import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
import { writeFile } from 'node:fs/promises';
const require = createRequire('/home/liuxuedeng/Django-Agent/packages/core/package.json');
const BetterSqlite3 = require('better-sqlite3');
const db = new BetterSqlite3(':memory:');
try {
  db.defaultSafeIntegers();
  db.exec("CREATE VIRTUAL TABLE chunks_fts USING fts5(content, tokenize='trigram')");
  const maximum = 9223372036854775807n;
  const ids = Array.from({ length: 64 }, (_, i) => maximum - BigInt(i));
  const entries = ids.flatMap((id, i) => [id, 'newtoken预算😀 original source ' + i]);
  const deletion = `DELETE FROM chunks_fts WHERE rowid IN (${ids.map(() => '?').join(',')})`;
  const insertion = `INSERT INTO chunks_fts(rowid,content) VALUES ${ids.map(() => '(?,?)').join(',')}`;
  const replacement = insertion.replace('INSERT INTO', 'INSERT OR REPLACE INTO');
  const query = (sql, parameters) => ({ sql, binds: parameters.length,
    query_plan: db.prepare('EXPLAIN QUERY PLAN ' + sql).all(...parameters),
    vm: db.prepare('EXPLAIN ' + sql).all(...parameters) });
  const proof = { connection: ':memory:', production_connection_opened: false,
    better_sqlite3_version: require('better-sqlite3/package.json').version,
    sqlite_version: db.prepare('SELECT sqlite_version() AS version').get().version,
    fts_schema: db.prepare("SELECT sql FROM sqlite_master WHERE name='chunks_fts'").get().sql,
    statement_plans: [query(deletion, ids), query(insertion, entries), query(replacement, entries)] };
  db.prepare('INSERT INTO chunks_fts(rowid,content) VALUES(?,?),(?,?)').run(maximum, 'oldtoken预算😀', maximum - 1n, 'unrelatedtoken来源');
  db.prepare('INSERT OR REPLACE INTO chunks_fts(rowid,content) VALUES(?,?)').run(maximum, 'newtoken预算😀');
  assert.equal(db.prepare('SELECT rowid FROM chunks_fts WHERE chunks_fts MATCH ?').get('newtoken').rowid, maximum);
  assert.equal(db.prepare('SELECT count(*) AS n FROM chunks_fts WHERE chunks_fts MATCH ?').get('oldtoken').n, 0n);
  assert.equal(db.prepare('SELECT rowid FROM chunks_fts WHERE chunks_fts MATCH ?').get('unrelatedtoken').rowid, maximum - 1n);
  const stable = db.prepare('SELECT rowid,content FROM chunks_fts ORDER BY rowid').all();
  assert.throws(() => db.transaction(() => {
    db.prepare('INSERT OR REPLACE INTO chunks_fts(rowid,content) VALUES(?,?)').run(maximum, 'failedtoken预算😀');
    throw new Error('fixture rollback');
  })(), /fixture rollback/);
  assert.deepEqual(db.prepare('SELECT rowid,content FROM chunks_fts ORDER BY rowid').all(), stable);
  db.prepare('DELETE FROM chunks_fts WHERE rowid=?').run(maximum);
  assert.equal(db.prepare('SELECT rowid FROM chunks_fts WHERE rowid=?').get(maximum), undefined);
  proof.small_semantic_proof = { passed: true, maximum_rowid_exact: true, old_terms_removed: true,
    current_terms_searchable: true, unrelated_row_preserved: true, transaction_rollback: true,
    inactive_still_requires_explicit_deletion: true,
    business_scope_and_global_sequence_fence_tested_here: false, performance_speedup_tested_here: false };
  const output = '/home/liuxuedeng/Django-Agent/docs/refactor-evidence/20261011-root-pub-current-profile/profile-analysis-sql-plan.json';
  await writeFile(output, JSON.stringify(proof, (_key, value) => typeof value === 'bigint' ? value.toString() : value, 2) + '\n');
  console.log(JSON.stringify({ output, sqlite: proof.sqlite_version, schema: proof.fts_schema,
    plans: proof.statement_plans.map(({ sql, binds, query_plan, vm }) => ({ sql, binds, query_plan,
      virtual_opcodes: vm.filter(row => ['VFilter', 'VNext', 'VUpdate'].includes(row.opcode)) })), proof: proof.small_semantic_proof },
    (_key, value) => typeof value === 'bigint' ? value.toString() : value));
} finally { db.close(); }
